import { Img, Lightning, Router } from '@lightningjs/sdk';
import List from '../components/list';
export default class Main extends Lightning.Component {
    static _template() {
        return {
            w: 1920 - 150,
            h: 1080,
            x: 150,
            Thumbnail: {
                x: (w) => w * 0.4,
                alpha: 1,
                texture: '',
                shader: {
                    type: Lightning.shaders.FadeOut,
                    left: 500,
                    bottom: 300
                },
                transitions: {
                    alpha: {
                        duration: 1000
                    }
                }
            },
            Metadata: {
                y: 150,
                Title: {
                    text: {
                        text: 'LIVE TV',
                        fontSize: 30,
                        fontStyle: 'bold',
                        wordWrap: true
                    }
                },
                Year: {
                    y: (h) => h + 55,
                    text: {
                        text: '',
                        fontSize: 25,
                        lineHeight: 55,
                        paddingLeft: 0,
                        fontStyle: 'bold',
                        wordWrap: true
                    }
                },
                Rate: {
                    y: (h) => h + 55,
                    x: 120,
                    text: {
                        text: '',
                        fontSize: 25,
                        lineHeight: 55,
                        paddingLeft: 0,
                        fontStyle: 'bold',
                        wordWrap: true
                    }
                },
                Overview: {
                    y: (h) => h + 130,
                    w: 800,
                    text: {
                        text: '',
                        fontSize: 23,
                        lineHeight: 40,
                        wordWrap: true
                    }
                }
            },
            MovieList: {
                y: (h) => h - 350,
                type: List,
                Title: {
                    y: -75,
                    text: {
                        text: 'MOST POPULAR',
                        fontSize: 35,
                        fontStyle: 'bold'
                    }
                }
            }
        };
    }
    _init() {
        const thumbnail = this.tag('Thumbnail');
        thumbnail.on('txLoaded', () => thumbnail.setSmooth('alpha', 1, { duration: 1 }));
    }
    $itemChanged(item) {
        const thumbnail = this.tag('Thumbnail');
        thumbnail.setSmooth('alpha', 0.01, { duration: 0.5 });
        thumbnail.texture = Img(`https://image.tmdb.org/t/p/original${item.backdrop_path}`).contain(1920 * 0.6, 1080 * 0.6);
        // txLoaded only fires when the displayed texture source changes, so an already-loaded texture must be faded in here
        if (thumbnail.texture.isLoaded()) {
            thumbnail.setSmooth('alpha', 1, { duration: 1 });
        }
        this.tag('Metadata').patch({
            Title: { text: { text: item.title || item.name } },
            Year: { text: { text: new Date(item.release_date || item.first_air_date).getFullYear() } },
            Rate: { text: { text: item.vote_average } },
            Overview: { text: { text: item.overview } }
        });
    }
    showPlaceholder() {
        this.tag('Thumbnail').texture = Img('/images/lightlex.png').contain(1920 * 0.6, 1080 * 0.6);
    }
    set tmdbData(data) {
        this.tag('MovieList').data = data;
    }
    _handleLeft() {
        Router.back();
    }
    _getFocused() {
        return this.tag('MovieList');
    }
    _active() {
        // TODO figure out why the back button turns the x to 0
        //console.log(this.x);
        this.patch({ x: 150 });
    }
}
